<?php require __DIR__.'/../app/bootstrap.php';$raw=file_get_contents('php://input');$sig=$_SERVER['HTTP_X_PAYSTACK_SIGNATURE']??'';$ps=new Paystack($config['paystack']['secret_key'],$config['app_url']);if(!$ps->validWebhook($raw,$sig)){http_response_code(401);exit('invalid');}$event=json_decode($raw,true);if(($event['event']??'')!=='charge.success'){http_response_code(200);exit('ok');}$d=$event['data']??[];$ref=$d['reference']??'';try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT * FROM funding_transactions WHERE reference=? FOR UPDATE');$s->execute([$ref]);$f=$s->fetch();if($f&&$f['status']!=='successful'&&($d['status']??'')==='success'&&(int)($d['amount']??0)===(int)round($f['amount']*100)){$pdo->prepare('UPDATE funding_transactions SET status="successful",provider_reference=? WHERE id=?')->execute([$ref,$f['id']]);$pdo->prepare('UPDATE wallets SET balance=balance+? WHERE user_id=?')->execute([$f['amount'],$f['user_id']]);$pdo->prepare('INSERT INTO wallet_transactions(user_id,type,amount,reference,description,status) VALUES(?,?,?,?,?,?)')->execute([$f['user_id'],'credit',$f['amount'],'WH-'.$ref,'Wallet funding (webhook)','successful']);}$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();http_response_code(500);exit('error');}echo 'ok';
